54	+    public async Task<StornierungErgebnis> BuchungStornierenAsync(string referenz)
55	+    {
56	+        var referenzNormalisiert = referenz.Trim().ToUpperInvariant();
57	+
58	+        await using var transaction = await db.Database.BeginTransactionAsync();
59	+
60	+        var aktualisierteZeilen = await db.Buchungen
61	+            .Where(b => b.Referenz == referenzNormalisiert && b.Status == BuchungStatus.Aktiv)
62	+            .ExecuteUpdateAsync(setter => setter.SetProperty(b => b.Status, BuchungStatus.Storniert));
63	+
64	+        if (aktualisierteZeilen == 0)
65	+        {
66	+            await transaction.RollbackAsync();
67	+            var existiert = await db.Buchungen.AnyAsync(b => b.Referenz == referenzNormalisiert);
68	+            return existiert ? StornierungErgebnis.BereitsStorniert() : StornierungErgebnis.NichtGefunden();
69	+        }
70	+
71	+        var buchungId = await db.Buchungen
72	+            .Where(b => b.Referenz == referenzNormalisiert)
73	+            .Select(b => b.Id)
74	+            .FirstAsync();
75	+
76	+        await db.Sitzplatzbelegungen
77	+            .Where(s => s.BuchungId == buchungId)
78	+            .ExecuteDeleteAsync();
79	+
80	+        await transaction.CommitAsync();
81	+
82	+        var aktualisiert = await BuchungAbrufenAsync(referenzNormalisiert);
83	+        return StornierungErgebnis.Erfolg(aktualisiert!);
84	+    }
85	 }
