1	import { CurrencyPipe, DatePipe } from '@angular/common';
2	import { Component, DestroyRef, ElementRef, inject, signal, viewChild } from '@angular/core';
3	import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
4	import { ActivatedRoute } from '@angular/router';
5	import { EMPTY, catchError, map, switchMap } from 'rxjs';
6	import { BuchungenService } from '../shared/api/buchungen.service';
7	import { BuchungDetail } from '../shared/models/buchung-detail';
8	import { BadgeStatus } from '../shared/ui/badge-status/badge-status';
9	import { Buchungsreferenz } from '../shared/ui/buchungsreferenz/buchungsreferenz';
10	import { spielstaettenOffset } from '../shared/utils/zeitzone';
11	
12	type Ladezustand = 'laedt' | 'geladen' | 'fehler';
13	
14	@Component({
15	  selector: 'app-buchungsdetail',
16	  imports: [CurrencyPipe, DatePipe, BadgeStatus, Buchungsreferenz],
17	  templateUrl: './buchungsdetail.html',
18	  styleUrl: './buchungsdetail.scss',
19	})
20	export class Buchungsdetail {
21	  private readonly buchungenService = inject(BuchungenService);
22	  private readonly route = inject(ActivatedRoute);
23	  private readonly destroyRef = inject(DestroyRef);
24	
25	  readonly ladezustand = signal<Ladezustand>('laedt');
26	  readonly buchung = signal<BuchungDetail | null>(null);
27	  readonly stornierungLaeuft = signal(false);
28	  readonly stornierungErfolgreich = signal(false);
29	  readonly stornierungFehler = signal<string | null>(null);
30	
31	  protected readonly spielstaettenOffset = spielstaettenOffset;
32	  private readonly stornierenDialog =
33	    viewChild.required<ElementRef<HTMLDialogElement>>('stornierenDialog');
34	
35	  constructor() {
36	    this.route.paramMap
37	      .pipe(
38	        map((paramMap) => paramMap.get('referenz')!),
39	        switchMap((referenz) => {
40	          this.ladezustand.set('laedt');
41	          return this.buchungenService.buchungAbrufen(referenz).pipe(
42	            catchError(() => {
43	              this.ladezustand.set('fehler');
44	              return EMPTY;
45	            }),
46	          );
47	        }),
48	        takeUntilDestroyed(),
49	      )
50	      .subscribe((buchung) => {
51	        this.buchung.set(buchung);
52	        this.ladezustand.set('geladen');
53	      });
54	  }
55	
56	  protected dialogOeffnen(): void {
57	    this.stornierungFehler.set(null);
58	    this.stornierenDialog().nativeElement.showModal();
59	  }
60	
61	  protected dialogAbbrechen(): void {
62	    this.stornierenDialog().nativeElement.close();
63	  }
64	
65	  protected stornierenBestaetigen(): void {
66	    const aktuelleBuchung = this.buchung();
67	    if (!aktuelleBuchung || this.stornierungLaeuft()) return;
68	
69	    this.stornierungLaeuft.set(true);
70	    this.buchungenService
71	      .buchungStornieren(aktuelleBuchung.referenz)
72	      .pipe(takeUntilDestroyed(this.destroyRef))
73	      .subscribe({
74	        next: (aktualisiert) => {
75	          this.stornierungLaeuft.set(false);
76	          this.buchung.set(aktualisiert);
77	          this.stornierungErfolgreich.set(true);
78	          this.stornierenDialog().nativeElement.close();
79	        },
80	        error: () => {
81	          this.stornierungLaeuft.set(false);
82	          this.stornierungFehler.set('Diese Buchung wurde bereits storniert.');
83	          this.stornierenDialog().nativeElement.close();
84	        },
85	      });
86	  }
87	}
